from __future__ import annotations

import os
from typing import Any, Dict, List, Optional

from azure.cosmos import CosmosClient, PartitionKey


def _normalize_items(items: Any) -> List[Dict[str, Any]]:
    if items is None:
        return []
    if isinstance(items, list):
        return items
    return list(items)


class CosmosNoSQLDocumentStore:
    def __init__(
        self,
        database_name: str,
        container_name: str,
        partition_key_path: str = "/partitionKey",
        endpoint: Optional[str] = None,
        key: Optional[str] = None,
    ) -> None:
        self.endpoint = endpoint or os.environ["AZURE_COSMOS_ENDPOINT"]
        self.key = key or os.environ["AZURE_COSMOS_KEY"]
        self.client = CosmosClient(self.endpoint, credential=self.key)

        self.database_name = database_name
        self.container_name = container_name
        self.partition_key_path = partition_key_path

        self.database = self.client.create_database_if_not_exists(id=self.database_name)
        self.container = self.database.create_container_if_not_exists(
            id=self.container_name,
            partition_key=PartitionKey(path=self.partition_key_path),
        )

    def query_by_field_value(
        self,
        field_name: str,
        field_value: Any,
        partition_key: Optional[Any] = None,
        max_item_count: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        query = f"SELECT * FROM c WHERE c.{field_name} = @value"
        parameters = [{"name": "@value", "value": field_value}]
        kwargs: Dict[str, Any] = {
            "query": query,
            "parameters": parameters,
        }
        if partition_key is not None:
            kwargs["partition_key"] = partition_key
        if max_item_count is not None:
            kwargs["max_item_count"] = max_item_count

        items = self.container.query_items(
            **kwargs,
            enable_cross_partition_query=partition_key is None,
        )
        return _normalize_items(items)

    def query_by_partition_key(
        self,
        partition_key_value: Any,
        filter_field_name: Optional[str] = None,
        filter_field_value: Optional[Any] = None,
        max_item_count: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        if filter_field_name is None:
            query = "SELECT * FROM c"
            parameters: List[Dict[str, Any]] = []
        else:
            query = f"SELECT * FROM c WHERE c.{filter_field_name} = @value"
            parameters = [{"name": "@value", "value": filter_field_value}]

        kwargs: Dict[str, Any] = {
            "query": query,
            "parameters": parameters,
            "partition_key": partition_key_value,
        }
        if max_item_count is not None:
            kwargs["max_item_count"] = max_item_count

        items = self.container.query_items(**kwargs)
        return _normalize_items(items)


def query_documents(
    *,
    database_name: str,
    container_name: str,
    field_name: Optional[str] = None,
    field_value: Optional[Any] = None,
    partition_key_value: Optional[Any] = None,
    partition_key_path: str = "/partitionKey",
    endpoint: Optional[str] = None,
    key: Optional[str] = None,
    max_item_count: Optional[int] = None,
) -> List[Dict[str, Any]]:
    store = CosmosNoSQLDocumentStore(
        database_name=database_name,
        container_name=container_name,
        partition_key_path=partition_key_path,
        endpoint=endpoint,
        key=key,
    )

    if partition_key_value is not None:
        return store.query_by_partition_key(
            partition_key_value=partition_key_value,
            filter_field_name=field_name,
            filter_field_value=field_value,
            max_item_count=max_item_count,
        )

    if field_name is None:
        raise ValueError("field_name must be provided when partition_key_value is not set")

    return store.query_by_field_value(
        field_name=field_name,
        field_value=field_value,
        max_item_count=max_item_count,
    )
